<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\Holder\UserGroupMembershipGroupsAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserGroupMembershipGroupsAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserGroupMembershipGroupsAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getGroups returns null on a freshly created holder.
     */
    public function testGroupsNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserGroupMembershipGroupsAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isGroupsAssigned());
        $this->assertNull($holder->getGroups());
    }
}
class ImplWithUserGroupMembershipGroupsAttributeHolderUnitTest
{
    use UserGroupMembershipGroupsAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedGroupsRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultGroups();
    }
}
